from collections import deque

def flood_fill_exterior(g, width, height):
    """Mark all cells reachable from edges as 'exterior'"""
    visited = [[False]*width for _ in range(height)]
    q = deque()

    # Start from all edge cells
    for c in range(width):
        q.append((0, c))
        q.append((height-1, c))
    for r in range(1, height-1):
        q.append((r, 0))
        q.append((r, width-1))

    while q:
        r, c = q.popleft()
        if visited[r][c]:
            continue
        visited[r][c] = True

        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < height and 0 <= nc < width and not visited[nr][nc]:
                q.append((nr, nc))

    return visited

def solve_demo(g_in, h, w):
    print("Input:")
    for row in g_in:
        print(row)

    # Flood fill from edges
