# Step 1: Find ALL valid rectangles (where all perimeter cells are 1)
valid_rectangles = []
for r1 in range(rows):
    for c1 in range(cols):
        if g_test_in[r1][c1] == 1:
            for r2 in range(r1, rows):
                for c2 in range(c1, cols):
                    if g_test_in[r2][c2] == 1 and r1 != r2 or c1 != c2:
                        # Check if all 4 edges are 1s
                        is_valid = True

                        # Top edge
                        for c in range(c1, c2+1):
