                                    is_valid = False
                                    break

                        if is_valid:
                            # Left edge
                            for r in range(r1, r2+1):
                                if g_test_in[r][c1] != 1:
                                    is_valid = False
                                    break

                        if is_valid:
                            # Right edge
                            for r in range(r1, r2+1):
                                if g_test_in[r][c2] != 1:
                                    is_valid = False
                                    break

                        if is_valid:
                            # Make sure we found at least a 2x2 rectangle (actual loop, not line)
                            if r2 - r1 >= 1 and c2 - c1 >= 1:
                                valid_rectangles.append((r1, c1, r2, c2))

print(f"Found {len(valid_rectangles)} valid rectangular loops")

# Remove duplicates (same bounds appearing multiple times)
unique_rects = list(set(valid_rectangles))
print(f"After deduplication: {len(unique_rects)} unique rectangles")

# Sort by area (descending) to process outer rectangles first
unique_rects.sort(key=lambda r: (r[2]-r[1]+1)*(r[3]-r[1]+1), reverse=True)

# Step 2: Apply transformation - create output grid
g_test_out = [[0]*cols for _ in range(rows)]

# Mark all 1s as 3 initially (will be overwritten by boundaries)
for r in range(rows):
    for c in range(cols):
        if g_test_in[r][c] == 1:
            g_test_out[r][c] = 3

# Track which interior cells are protected by smaller rectangles
protected_interior = set()

# Process rectangles from largest to smallest
for r1, c1, r2, c2 in unique_rects:
    interior_cells = set()
    for r in range(r1+1, r2):
        for c in range(c1+1, c2):
            interior_cells.add((r,c))

    # Count how many rectangles cover each interior cell
    coverage = defaultdict(int)
    for rr, cc, er, ec in unique_rects:
        if r1 < rr < r2 and c1 < cc < c2:
            for r in range(rr+1, er):
                for c in range(cc+1, ec):
                    coverage[(r,c)] += 1

    # If interior cell is covered by smaller rectangles, mark as protected
    for cell in interior_cells:
        if coverage[cell] > 0:
            protected_interior.add(cell)

# Now apply actual transformation
for r1, c1, r2, c2 in unique_rects:
    # Boundary cells become 2
    for c in range(c1, c2+1):
        g_test_out[r1][c] = 2
        g_test_out[r2][c] = 2
    for r in range(r1, r2+1):
        g_test_out[r][c1] = 2
        g_test_out[r][c2] = 2

    # Interior cells: if protected by smaller rects, keep as 1, otherwise 3
    for r in range(r1+1, r2):
        for c in range(c1+1, c2):
            if (r,c) in protected_interior:
                g_test_out[r][c] = 1
            else:
                g_test_out[r][c] = 3

# Print some verification
